@import "tailwindcss";

@import url('https://fonts.googleapis.com/css2?family=Google+Sans+Flex:opsz,wght@1..144,1..1000&display=swap');

/* ============================================================================
   DHAMINI DESIGN SYSTEM — Modern Savanna
   Palette inspired by African earth: terracotta, deep savanna green, gold.
   Competent, cohesive, not over-stimulating.
   ============================================================================ */

@layer base {
  :root {
    /* ---- Color Palette ---- */
    --background: 0 0 6%;        /* #0f111a - warm deep slate */
    --foreground: 210 40 96%;    /* #f3f4f6 - warm off-white */

    --card: 0 0 12%;
    --card-foreground: 210 40 96%;

    --popover: 0 0 12%;
    --popover-foreground: 210 40 96%;

    /* Primary: Terracotta / Burnt Clay (#c2410c) */
    --primary: 18 89 39%;
    --primary-foreground: 210 40 98%;

    /* Secondary: Deep Savanna Green (#14532d) */
    --secondary: 150 47 18%;
    --secondary-foreground: 210 40 96%;

    /* Accent: African Gold / Amber (#d97706) */
    --accent: 37 84 43%;
    --accent-foreground: 210 40 98%;

    --muted: 215 16 27%;
    --muted-foreground: 215 14 65%;

    --destructive: 0 62 30%;
    --destructive-foreground: 210 40 98%;

    --border: 215 16 30%;
    --input: 215 16 27%;
    --ring: 18 89 39%;

    --radius: 0.75rem;

    /* ---- Semantic colors ---- */
    --brand-terracotta: #c2410c;
    --brand-terracotta-glow: rgba(194, 65, 12, 0.25);
    --brand-green: #14532d;
    --brand-green-glow: rgba(20, 83, 45, 0.2);
    --brand-gold: #d97706;
    --brand-gold-glow: rgba(217, 119, 6, 0.25);
    --brand-slate: #0f111a;
    --brand-surface: #1f2937;
    --brand-text: #f3f4f6;
    --brand-text-muted: #94a3b8;
    --brand-border: #374151;

    /* ---- Typography ---- */
    --font-sans: 'Google Sans Flex', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

    /* ---- Motion ---- */
    --transition-smooth: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --transition-bounce: 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);

    /* ---- Shadows ---- */
    --shadow-terracotta: 0 10px 25px -5px rgba(194, 65, 12, 0.15);
    --shadow-green: 0 10px 25px -5px rgba(20, 83, 45, 0.12);
    --shadow-gold: 0 10px 25px -5px rgba(217, 119, 6, 0.15);
  }

  .dark {
    /* Same values — Dhamini is dark-first */
  }

  body {
    background-color: hsl(var(--background));
    color: hsl(var(--foreground));
    font-family: var(--font-sans);
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
    overflow-x: hidden;
  }

  /* Remove default margins/paddings */
  * {
    box-sizing: border-box;
  }

  html, body, #root {
    height: 100%;
  }
}

@layer components {
  /* ---- Glass card ---- */
  .d-card {
    @apply relative rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] bg-opacity-90 backdrop-blur-md transition-all duration-300;
  }

  .d-card:hover {
    @apply border-[hsl(var(--primary))]/40 shadow-[var(--shadow-terracotta)];
  }

  /* ---- Primary button ---- */
  .d-btn-primary {
    @apply inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-6 py-3 text-[hsl(var(--primary-foreground))] font-semibold text-sm transition-all duration-200 hover:bg-[hsl(var(--primary))/90] hover:shadow-[var(--shadow-terracotta)] active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[hsl(var(--ring))] focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none;
  }

  /* ---- Secondary button ---- */
  .d-btn-secondary {
    @apply inline-flex items-center justify-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--secondary))]/30 px-6 py-3 text-[hsl(var(--secondary-foreground))] font-semibold text-sm transition-all duration-200 hover:bg-[hsl(var(--secondary))]/50 hover:border-[hsl(var(--secondary))]/60 active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[hsl(var(--ring))] disabled:opacity-50 disabled:pointer-events-none;
  }

  /* ---- Ghost button ---- */
  .d-btn-ghost {
    @apply inline-flex items-center justify-center gap-2 rounded-xl px-6 py-3 text-[hsl(var(--muted-foreground))] font-semibold text-sm transition-all duration-200 hover:bg-[hsl(var(--muted))] active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[hsl(var(--ring))] disabled:opacity-50 disabled:pointer-events-none;
  }

  /* ---- Gold accent button (CTA) ---- */
  .d-btn-gold {
    @apply inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--accent))] px-6 py-3 text-[hsl(var(--accent-foreground))] font-bold text-sm tracking-wide transition-all duration-200 hover:bg-[hsl(var(--accent))/90] hover:shadow-[var(--shadow-gold)] active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[hsl(var(--ring))] disabled:opacity-50 disabled:pointer-events-none;
  }

  /* ---- Badge ---- */
  .d-badge {
    @apply inline-flex items-center rounded-full border px-3 py-1 text-[10px] font-semibold tracking-wide transition-colors;
  }

  .d-badge-terracotta {
    @apply border-[hsl(var(--primary))]/30 bg-[hsl(var(--primary))]/10 text-[hsl(var(--primary))];
  }

  .d-badge-green {
    @apply border-[hsl(var(--secondary))]/30 bg-[hsl(var(--secondary))]/10 text-[hsl(var(--secondary))];
  }

  .d-badge-gold {
    @apply border-[hsl(var(--accent))]/30 bg-[hsl(var(--accent))]/10 text-[hsl(var(--accent))];
  }

  .d-badge-slate {
    @apply border-[hsl(var(--border))] bg-[hsl(var(--muted))]/50 text-[hsl(var(--muted-foreground))];
  }

  /* ---- Input ---- */
  .d-input {
    @apply flex h-11 w-full rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-2 text-sm text-[hsl(var(--foreground))] placeholder-[hsl(var(--muted-foreground))]/60 transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-[hsl(var(--ring))] focus:border-[hsl(var(--ring))] disabled:cursor-not-allowed disabled:opacity-50;
  }

  /* ---- KPI Card ---- */
  .d-kpi {
    @apply d-card p-5 overflow-hidden;
  }

  .d-kpi-label {
    @apply text-[11px] font-semibold tracking-wider uppercase text-[hsl(var(--muted-foreground))];
  }

  .d-kpi-value {
    @apply mt-1 text-2xl font-black text-[hsl(var(--foreground))] tracking-tight;
  }

  .d-kpi-trend {
    @apply mt-2 text-[11px] font-semibold;
  }

  /* ---- Mouse-follow ambient glow ---- */
  .ambient-glow {
    @apply fixed top-0 left-0 w-full h-full -z-10 pointer-events-none overflow-hidden;
  }

  .glow-orb {
    @apply absolute rounded-full blur-[120px] opacity-30 transition-opacity duration-1000 ease-out;
  }

  /* ---- Section separator ---- */
  .d-section {
    @apply relative py-16 lg:py-24 border-t border-[hsl(var(--border))]/50;
  }

  .d-section-header {
    @apply mb-12 text-center;
  }

  .d-section-kicker {
    @apply inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-[hsl(var(--primary))]/10 border border-[hsl(var(--primary))]/20 text-[hsl(var(--primary))] text-[10px] font-semibold tracking-wider uppercase mb-4;
  }

  .d-section-title {
    @apply text-3xl lg:text-5xl font-black text-[hsl(var(--foreground))] tracking-tight mb-6 leading-tight;
  }

  .d-section-subtitle {
    @apply text-lg text-[hsl(var(--muted-foreground))] max-w-2xl mx-auto leading-relaxed;
  }
}

@layer utilities {
  /* Text gradient for headings */
  .text-gradient-terracotta {
    @apply bg-[linear-gradient(to_right,hsl(var(--primary)),hsl(var(--accent)))] bg-clip-text text-transparent;
  }

  .text-gradient-green {
    @apply bg-[linear-gradient(to_right,hsl(var(--secondary)),#10b981)] bg-clip-text text-transparent;
  }

  /* Glassmorphism utilities */
  .glass {
    @apply bg-[hsl(var(--card))]/80 backdrop-blur-md border border-[hsl(var(--border))]/50;
  }

  /* Reveal animation */
  .reveal {
    @apply opacity-0 translate-y-4 transition-all duration-700 ease-out;
  }

  .reveal.visible {
    @apply opacity-100 translate-y-0;
  }

  /* Staggered children */
  .stagger > * {
    @apply opacity-0 translate-y-2;
  }

  .stagger.visible > * {
    @apply opacity-100 translate-y-0 transition-all duration-500 ease-out;
  }

  /* Scrollbar */
  .scrollbar-thin::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }
  .scrollbar-thin::-webkit-scrollbar-track {
    background: hsl(var(--muted));
  }
  .scrollbar-thin::-webkit-scrollbar-thumb {
    background: hsl(var(--border));
    border-radius: 3px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background: hsl(var(--primary));
  }
}

