import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  Briefcase,
  Gamepad2,
  ShieldCheck,
  ArrowRight,
  Lock,
  User,
  Mail,
  Phone,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/Card';
import { api } from '@/lib/api';

export const Login = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [role, setRole] = useState<'brand' | 'creator' | null>(
    (searchParams.get('role') as 'brand' | 'creator') || null
  );
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [demoAccounts, setDemoAccounts] = useState<any[]>([]);

  useEffect(() => {
    api.getDemoAccounts().then((data) => {
      setDemoAccounts(data.creators || []);
    });
  }, []);

  const handleRoleSelect = (r: 'brand' | 'creator') => {
    setRole(r);
    setError(null);
  };

  const handleDemoLogin = async (account: any) => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await api.login({
        role: account.role,
        demo_id: account.id || account.demo_id,
      });
      navigate(res.redirect_url, { replace: true });
    } catch (err: any) {
      setError(err.message || 'Login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleManualLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);
    try {
      const formData = new FormData(e.currentTarget);
      const identifier = formData.get('identifier') as string;
      const password = formData.get('password') as string;
      const res = await api.login({
        role: role!,
        identifier,
        password,
      });
      navigate(res.redirect_url, { replace: true });
    } catch (err: any) {
      setError(err.message || 'Invalid credentials. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const brandDemo = {
    id: 'brand-simulation-account',
    name: 'Safaricom 5G Gaming Hub',
    email: 'brand@sponsorplay.ke',
    role: 'brand' as const,
    avatar_text: 'SAF',
    location: 'Nairobi HQ, Kenya',
    budget_usd: 10000,
    tier: 'ENTERPRISE_SPONSOR',
  };

  const getRoleConfig = () => {
    if (role === 'brand') {
      return {
        title: 'Brand Sponsor Login',
        subtitle:
          'Access campaign management, milestone tracking, and KRA eTIMS tax invoices.',
        icon: Briefcase,
        primaryAction: 'Start Sponsoring',
      };
    }
    if (role === 'creator') {
      return {
        title: 'Creator / Talent Login',
        subtitle:
          'Review offers, upload deliverables, track payouts, and build your Skills Passport.',
        icon: Gamepad2,
        primaryAction: 'Open Creator Portal',
      };
    }
    return null;
  };

  const config = getRoleConfig();

  if (!role) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center px-4 bg-[hsl(var(--background))]">
        <div className="max-w-md w-full text-center">
          <div className="flex items-center justify-center gap-2 mb-6">
            <div className="h-12 w-12 rounded-2xl bg-gradient-to-tr from-[hsl(var(--primary))] to-[hsl(var(--accent))] flex items-center justify-center shadow-[var(--shadow-terracotta)]">
              <Gamepad2 className="h-6 w-6 text-white" />
            </div>
            <span className="font-extrabold text-2xl tracking-tight bg-gradient-to-r from-white via-slate-200 to-[hsl(var(--accent))] bg-clip-text text-transparent">
              DHAMINI
            </span>
          </div>

          <h1 className="text-3xl font-black text-[hsl(var(--foreground))] mb-4">Select your role</h1>
          <p className="text-lg text-[hsl(var(--muted-foreground))] mb-10">
            Are you a corporate brand or a gaming creator?
          </p>

          <div className="grid grid-cols-2 gap-4 mb-10">
            <Button
              variant="ghost"
              size="lg"
              onClick={() => handleRoleSelect('brand')}
              className="border border-[hsl(var(--border))] hover:bg-[hsl(var(--primary))]/10 hover:text-[hsl(var(--primary))]"
            >
              <Briefcase className="h-5 w-5 mr-2" />
              Brand Sponsor
            </Button>
            <Button
              variant="gold"
              size="lg"
              onClick={() => handleRoleSelect('creator')}
            >
              <Gamepad2 className="h-5 w-5 mr-2" />
              Creator / Talent
            </Button>
          </div>

          <div className="grid md:grid-cols-2 gap-6 text-left">
            <div className="p-5 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]/50">
              <h3 className="font-bold text-[hsl(var(--foreground))] mb-2">For Brands</h3>
              <p className="text-sm text-[hsl(var(--muted-foreground))] mb-4">
                Submit briefs, manage campaigns, verify deliverables, download tax invoices.
              </p>
              <ul className="text-xs text-[hsl(var(--muted-foreground))] space-y-1">
                <li>• Campaign briefs</li>
                <li>• Milestone escrow</li>
                <li>• eTIMS invoices</li>
                <li>• Impact dashboards</li>
              </ul>
            </div>
            <div className="p-5 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]/50">
              <h3 className="font-bold text-[hsl(var(--foreground))] mb-2">For Creators</h3>
              <p className="text-sm text-[hsl(var(--muted-foreground))] mb-4">
                Browse offers, accept contracts, upload deliverables, get paid.
              </p>
              <ul className="text-xs text-[hsl(var(--muted-foreground))] space-y-1">
                <li>• Offer management</li>
                <li>• Deliverable upload</li>
                <li>• PayPal / M-Pesa</li>
                <li>• Skills Passport</li>
              </ul>
            </div>
          </div>

          <p className="text-xs text-[hsl(var(--muted-foreground))] mt-6 uppercase tracking-wider">
            Dhamini — Sponsoring African Gaming Talent
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-4 bg-[hsl(var(--background))]">
      <div className="max-w-md w-full">
        <div className="flex items-center justify-center gap-2 mb-8">
          <div className="h-12 w-12 rounded-2xl bg-gradient-to-tr from-[hsl(var(--primary))] to-[hsl(var(--accent))] flex items-center justify-center shadow-[var(--shadow-terracotta)]">
            {config.icon && <config.icon className="h-6 w-6 text-white" />}
          </div>
          <span className="font-extrabold text-2xl tracking-tight bg-gradient-to-r from-white via-slate-200 to-[hsl(var(--accent))] bg-clip-text text-transparent">
            DHAMINI
          </span>
        </div>

        <Card padding="lg">
          <CardHeader className="space-y-2">
            <CardTitle className="text-2xl">{config.title}</CardTitle>
            <CardDescription>{config.subtitle}</CardDescription>
          </CardHeader>

          <CardContent className="space-y-6">
            {error && (
              <div className="p-4 rounded-xl border border-red-500/30 bg-red-900/20 text-red-300 text-sm">
                {error}
              </div>
            )}

            {/* Quick demo login (for piloting/evaluation) */}
            <div className="space-y-3">
              <p className="text-xs font-semibold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">
                Quick Access (Demo)
              </p>
              <div className="flex flex-col gap-3">
                {role === 'brand' ? (
                  <Button
                    variant="ghost"
                    className="w-full text-left justify-start border border-[hsl(var(--border))] hover:bg-[hsl(var(--primary))]/10"
                    onClick={() => handleDemoLogin(brandDemo)}
                  >
                    <Lock className="h-4 w-4 mr-3 text-[hsl(var(--muted-foreground))]" />
                    <span className="font-medium">Safaricom 5G Gaming Hub</span>
                    <span className="ml-auto text-xs text-[hsl(var(--muted-foreground))]">
                      brand@sponsorplay.ke
                    </span>
                  </Button>
                ) : (
                  demoAccounts.map((creator) => (
                    <Button
                      key={creator.id}
                      variant="ghost"
                      className="w-full text-left justify-start border border-[hsl(var(--border))] hover:bg-emerald-900/20"
                      onClick={() => handleDemoLogin(creator)}
                    >
                      <Gamepad2 className="h-4 w-4 mr-3 text-emerald-400" />
                      <div className="flex-1">
                        <span className="font-medium text-[hsl(var(--foreground))]">
                          {creator.name} (@{creator.gamer_tag})
                        </span>
                        <span className="text-xs text-[hsl(var(--muted-foreground))]">
                          {creator.type} • {creator.location}
                        </span>
                      </div>
                      <span className="text-xs text-emerald-400">
                        ${creator.base_rate_usd}
                      </span>
                    </Button>
                  ))
                )}
              </div>
            </div>

            <div className="h-px bg-[hsl(var(--border))] my-2" />

            {/* Manual login form */}
            <form onSubmit={handleManualLogin} className="space-y-4">
              <Input
                label="Email / Gamer Tag / Brand Name"
                placeholder={role === 'brand' ? 'brand@sponsorplay.ke' : 'creator@sponsorplay.ke'}
                name="identifier"
                required
              />
              <Input
                label="Password"
                type="password"
                placeholder="demo123"
                name="password"
                required
              />
              <Button
                variant="primary"
                className="w-full"
                isLoading={isLoading}
                disabled={isLoading}
              >
                {config.primaryAction}
              </Button>
            </form>

            <p className="text-xs text-center text-[hsl(var(--muted-foreground))]">
              Demo credentials: email above / password{" "}
              <span className="font-medium text-[hsl(var(--foreground))]">demo123</span>
            </p>
          </CardContent>
        </Card>

        <div className="mt-8 text-center">
          <Button variant="ghost" size="sm" onClick={() => setRole(null)}>
            <ArrowRight className="h-4 w-4 mr-2" /> Back to role selection
          </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Briefcase,
  DollarSign,
  ShieldCheck,
  ArrowRight,
  Users,
  Trophy,
  FileText,
  Clock,
  Plus,
  Mail,
  Search,
  Filter,
  Download,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Input } from '@/components/ui/Input';
import { KPICard } from '@/components/ui/KPICard';
import { api, formatUSD, formatKES, formatDate, getStatusColor } from '@/lib/api';

interface CampaignCardProps {
  id: string;
  brand_name: string;
  budget_usd: number;
  status: string;
  target_audience: string;
  created_at: string;
  creator_count?: number;
}

export const BrandDashboard = () => {
  const navigate = useNavigate();
  const [campaigns, setCampaigns] = useState<CampaignCardProps[]>([]);
  const [creators, setCreators] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const kpiData = [
    {
      title: 'Active Campaigns',
      value: campaigns.length,
      trend: { label: 'vs last month', value: '+12%', positive: true },
      icon: <Briefcase className="h-5 w-5" />,
      iconColor: 'text-blue-400',
    },
    {
      title: 'Budget Committed',
      value: formatUSD(
        campaigns.reduce((sum, c) => sum + c.budget_usd, 0)
      ),
      trend: { label: 'KES equivalent', value: formatKES(campaigns.reduce((sum, c) => sum + c.budget_usd, 0) * 130), positive: true },
      icon: <DollarSign className="h-5 w-5" />,
      iconColor: 'text-[hsl(var(--primary))]',
    },
    {
      title: 'Tax Invoices Issued',
      value: 0,
      trend: { label: 'KRA eTIMS compliant', value: '100%', positive: true },
      icon: <FileText className="h-5 w-5" />,
      iconColor: 'text-[hsl(var(--secondary))]',
    },
    {
      title: 'Creators Sponsored',
      value: creators.length,
      trend: { label: 'Active syndicates', value: '3', positive: true },
      icon: <Users className="h-5 w-5" />,
      iconColor: 'text-purple-400',
    },
  ];

  const filteredCampaigns = campaigns.filter((c) => {
    const matchesSearch =
      c.brand_name.toLowerCase().includes(search.toLowerCase()) ||
      c.target_audience.toLowerCase().includes(search.toLowerCase());
    const matchesStatus =
      statusFilter === 'all' || c.status.toLowerCase() === statusFilter;
    return matchesSearch && matchesStatus;
  });

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      try {
        const [creatorsData, campaignsData] = await Promise.all([
          api.listCreators(),
          api.listSeedCampaigns(),
        ]);
        setCreators(creatorsData);
        setCampaigns(
          campaignsData.map((c) => ({
            id: c.id,
            brand_name: c.brand_name,
            budget_usd: c.budget_usd,
            status: c.status || 'ACTIVE',
            target_audience: c.target_audience,
            created_at: c.created_at || new Date().toISOString(),
            creator_count: 3,
          }))
        );
      } catch (err) {
        console.error('Failed to load dashboard data', err);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  const handleSubmitBrief = () => {
    navigate('/brand/brief');
  };

  const handleViewCampaign = (id: string) => {
    navigate(`/brand/campaigns/${id}`);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[hsl(var(--background))] flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="h-8 w-8 border-4 border-[hsl(var(--primary))]/30 border-t-[hsl(var(--primary))] rounded-full animate-spin" />
          <p className="text-sm text-[hsl(var(--muted-foreground))]">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[hsl(var(--background))]">
      {/* Top App Bar */}
      <div className="border-b border-[hsl(var(--border))] bg-[hsl(var(--card))]/50 backdrop-blur sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 py-6">
            <div className="flex items-center gap-3">
              <h1 className="text-xl font-bold text-[hsl(var(--foreground))]">
                Brand Dashboard
              </h1>
              <Badge variant="terracotta">Safemode: Live</Badge>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
              <div className="relative w-full lg:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[hsl(var(--muted-foreground))]" />
                <Input
                  placeholder="Search campaigns, brands, creators..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-10"
                  label={undefined}
                />
              </div>
              <Button
                variant="gold"
                onClick={handleSubmitBrief}
                leftIcon={<Plus className="h-4 w-4" />}
              >
                New Campaign
              </Button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* KPI Row */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
          {kpiData.map((kpi) => (
            <KPICard key={kpi.title} {...kpi} />
          ))}
        </div>

        {/* Campaigns Section */}
        <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 mb-6">
          <div>
            <h2 className="text-lg font-bold text-[hsl(var(--foreground))]">
              Active Campaigns
            </h2>
            <p className="text-sm text-[hsl(var(--muted-foreground))]">
              Track budget, milestones, and verification status.
            </p>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={() => setStatusFilter('all')}>
              All
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className={statusFilter === 'active' ? 'bg-[hsl(var(--secondary))]/10 text-[hsl(var(--secondary))]' : ''}
              onClick={() => setStatusFilter('active')}
            >
              Active
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className={statusFilter === 'draft' ? 'bg-red-900/20 text-red-400' : ''}
              onClick={() => setStatusFilter('draft')}
            >
              Draft
            </Button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="border-b border-[hsl(var(--border))]">
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                  Campaign
                </th>
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                  Budget
                </th>
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                  Audience
                </th>
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                  Status
                </th>
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                  Created
                </th>
                <th className="pb-3 text-xs font-semibold text-[hsl(var(--muted-foreground))] uppercase tracking-wider text-right">
                  Action
                </th>
              </tr>
            </thead>
            <tbody>
              {filteredCampaigns.length > 0 ? (
                filteredCampaigns.map((campaign) => (
                  <tr
                    key={campaign.id}
                    className="border-b border-[hsl(var(--border))]/50 hover:bg-[hsl(var(--card))]/30 transition-colors cursor-pointer group"
                    onClick={() => handleViewCampaign(campaign.id)}
                  >
                    <td className="py-4">
                      <div className="flex items-center gap-3">
                        <div className="h-10 w-10 rounded-xl bg-[hsl(var(--card))] border border-[hsl(var(--border))] flex items-center justify-center">
                          <Users className="h-5 w-5 text-[hsl(var(--muted-foreground))]" />
                        </div>
                        <div>
                          <p className="font-medium text-[hsl(var(--foreground))]">{campaign.brand_name}</p>
                          <p className="text-xs text-[hsl(var(--muted-foreground))]">
                            {campaign.creator_count} creators matched
                          </p>
                        </div>
                      </div>
                    </td>
                    <td className="py-4">
                      <p className="font-medium text-[hsl(var(--foreground))]">
                        {formatUSD(campaign.budget_usd)}
                      </p>
                      <p className="text-xs text-[hsl(var(--muted-foreground))]">
                        {formatKES(campaign.budget_usd * 130)}
                      </p>
                    </td>
                    <td className="py-4">
                      <p className="text-sm text-[hsl(var(--foreground))]">
                        {campaign.target_audience}
                      </p>
                    </td>
                    <td className="py-4">
                      <span
                        className={`px-2.5 py-1 rounded-full text-xs font-bold ${getStatusColor(campaign.status)}`}
                      >
                        {campaign.status.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td className="py-4">
                      <p className="text-xs text-[hsl(var(--muted-foreground))]">
                        {formatDate(campaign.created_at)}
                      </p>
                    </td>
                    <td className="py-4 text-right">
                      <Button variant="ghost" size="sm" className="p-2">
                        <ArrowRight className="h-4 w-4" />
                      </Button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="py-12 text-center">
                    <p className="text-[hsl(var(--muted-foreground))]">
                      No campaigns found.
                    </p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Quick Actions */}
        <div className="mt-12 grid md:grid-cols-3 gap-6">
          <Card padding="md" hoverable>
            <CardHeader>
              <CardTitle className="text-lg">Submit Brief</CardTitle>
              <CardDescription>
                AI-matched syndicates within 24 hours.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Button variant="outline" className="w-full" onClick={handleSubmitBrief}>
                Create Brief
              </Button>
            </CardContent>
          </Card>

          <Card padding="md" hoverable>
            <CardHeader>
              <CardTitle className="text-lg">Tax Invoices</CardTitle>
              <CardDescription>
                Download certified KRA eTIMS BII receipts.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Button variant="outline" className="w-full">
                <Download className="h-4 w-4 mr-2" />
                View Invoices
              </Button>
            </CardContent>
          </Card>

          <Card padding="md" hoverable>
            <CardHeader>
              <CardTitle className="text-lg">Impact Dossier</CardTitle>
              <CardDescription>
                C-suite sustainability and reach reporting.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Button variant="outline" className="w-full">
                <FileText className="h-4 w-4 mr-2" />
                Generate Report
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
};

