                        <CardDescription>
                          {formatUSD(deal.total_budget_usd)} • {deal.milestones.length} milestones
                        </CardDescription>
                      </CardHeader>
                      <CardContent className="pt-0">
                        <div className="space-y-3">
                          {deal.milestones.map((m: any, idx: number) => (
                            <div
                              key={m.id}
                              className="flex items-center justify-between p-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--background))]/30"
                            >
                              <div className="flex items-center gap-3">
                                <div className="h-6 w-6 rounded-full bg-[hsl(var(--card))] flex items-center justify-center">
                                  <span className="text-xs font-bold">{idx + 1}</span>
                                </div>
                                <p className="text-sm text-[hsl(var(--foreground))]">{m.title}</p>
                              </div>
                              <span
                                className={`px-2 py-0.5 rounded text-[10px] font-bold ${getStatusColor(m.status)}`}
                              >
                                {m.status.replace(/_/g, ' ')}
                              </span>
                            </div>
                          ))}
                        </div>
                      </CardContent>
                      <CardFooter>
                        <Button variant="ghost" size="sm" onClick={handleUploadDeliverable}>
                          <Upload className="h-4 w-4 mr-2" />
                          Upload Deliverable
                        </Button>
                      </CardFooter>
                    </Card>
                  ))}
                </div>
              ) : (
                <Card padding="lg" className="text-center">
                  <div className="flex flex-col items-center gap-3">
                    <Trophy className="h-10 w-10 text-[hsl(var(--muted-foreground))]" />
                    <h4 className="font-medium text-[hsl(var(--foreground))]">No active deals</h4>
                    <p className="text-sm text-[hsl(var(--muted-foreground))]">
                      Accept an offer to start working on milestones.
                    </p>
                  </div>
                </Card>
              )}
            </div>
          )}

          {/* Completed Deals */}
          {activeTab === 'completed' && (
            <div>
              <h3 className="text-lg font-bold text-[hsl(var(--foreground))] mb-4">
                Completed Deals
              </h3>
              {dashboard!.completed_deals.length > 0 ? (
                <div className="space-y-4">
                  {dashboard!.completed_deals.map((deal: any) => (
                    <Card key={deal.id} padding="md">
                      <div className="flex justify-between items-start">
                        <div>
                          <h4 className="font-bold text-[hsl(var(--foreground))]">
                            {deal.campaign?.brand_name || 'Completed Campaign'}
                          </h4>
                          <p className="text-sm text-[hsl(var(--muted-foreground))]">
                            Paid: {formatUSD(deal.net_creator_disbursement_usd)}
                          </p>
                        </div>
                        <Badge variant="green">Paid</Badge>
                      </div>
                    </Card>
                  ))}
                </div>
              ) : (
                <Card padding="lg" className="text-center">
                  <div className="flex flex-col items-center gap-3">
                    <FileText className="h-10 w-10 text-[hsl(var(--muted-foreground))]" />
                    <h4 className="font-medium text-[hsl(var(--foreground))]">No completed deals yet</h4>
                    <p className="text-sm text-[hsl(var(--muted-foreground))]">
                      Complete milestones to build your track record.
                    </p>
                  </div>
                </Card>
              )}
            </div>
          )}

          {/* Certificates */}
          {activeTab === 'certificates' && (
            <div>
              <h3 className="text-lg font-bold text-[hsl(var(--foreground))] mb-4">
                Proof-of-Play Certificates
              </h3>
              {dashboard!.certificates.length > 0 ? (
                <div className="grid md:grid-cols-2 gap-4">
                  {dashboard!.certificates.map((cert: any) => (
                    <Card key={cert.certificate_id} padding="md">
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h4 className="font-bold text-[hsl(var(--foreground))]">
                            Certificate of Verification
                          </h4>
                          <p className="text-xs text-[hsl(var(--muted-foreground))]">
                            {cert.certificate_id}
                          </p>
                        </div>
                        <span
                          className={`px-2.5 py-1 rounded text-[10px] font-bold ${getDecisionColor(cert.verification_decision)}`}
                        >
                          {cert.verification_decision}
                        </span>
                      </div>
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-[hsl(var(--muted-foreground))]">Logo Screen Time</span>
                          <span className="font-medium text-[hsl(var(--foreground))]">
                            {cert.logo_screen_ratio_percent}%
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-[hsl(var(--muted-foreground))]">Airtime</span>
                          <span className="font-medium text-[hsl(var(--foreground))]">
                            {Math.floor(cert.airtime_seconds / 60)} min
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-[hsl(var(--muted-foreground))]">Confidence</span>
                          <span className="font-medium text-[hsl(var(--foreground))]">
                            {cert.overall_confidence_percent}%
                          </span>
                        </div>
                      </div>
                    </Card>
                  ))}
                </div>
              ) : (
                <Card padding="lg" className="text-center">
                  <div className="flex flex-col items-center gap-3">
                    <ShieldCheck className="h-10 w-10 text-[hsl(var(--muted-foreground))]" />
                    <h4 className="font-medium text-[hsl(var(--foreground))]">No certificates yet</h4>
                    <p className="text-sm text-[hsl(var(--muted-foreground))]">
                      Verified deliverables generate cryptographic certificates here.
                    </p>
                  </div>
                </Card>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/* ============================================================================
   DHAMINI — App Shell
   Client-side routing with role-based dashboards
   ============================================================================ */

import React, { useState, useEffect } from 'react';
import { Navbar } from '@/components/layout/Navbar';
import { Footer } from '@/components/layout/Footer';
import { Landing } from '@/pages/Landing';
import { Login } from '@/pages/Login';
import { BrandDashboard } from '@/pages/BrandDashboard';
import { CreatorDashboard } from '@/pages/CreatorDashboard';
import { api, getSessionToken, getSessionRole, clearSession } from '@/lib/api';

type Route =
  | 'landing'
  | 'login'
  | 'brand'
  | 'creator'
  | 'brand-brief'
  | 'brand-campaigns'
  | 'brand-tax'
  | 'creator-offers'
  | 'creator-deliverables'
  | 'creator-certificates';

export function App() {
  const [route, setRoute] = useState<Route>('landing');
  const [role, setRole] = useState<'brand' | 'creator' | null>(null);

  /* Restore session from cookie on mount */
  useEffect(() => {
    const token = getSessionToken();
    const savedRole = getSessionRole();
    if (token && savedRole) {
      setRole(savedRole);
      setRoute(savedRole === 'brand' ? 'brand' : 'creator');
    }
  }, []);

  const handleNavigate = (path: string) => {
    // Map URL paths to internal routes
    const map: Record<string, Route> = {
      '/': 'landing',
      '/login': 'login',
      '/brand': 'brand',
      '/creator': 'creator',
      '/brand/brief': 'brand-brief',
      '/brand/campaigns': 'brand-campaigns',
      '/brand/tax': 'brand-tax',
      '/creator/offers': 'creator-offers',
      '/creator/deliverables': 'creator-deliverables',
      '/creator/certificates': 'creator-certificates',
    };
    const r = map[path];
    if (r) {
      setRoute(r);
      window.history.pushState({}, '', path);
    }
  };

  const handleLogin = (userRole: 'brand' | 'creator') => {
    setRole(userRole);
    setRoute(userRole === 'brand' ? 'brand' : 'creator');
    window.history.pushState({}, '', userRole === 'brand' ? '/brand' : '/creator');
  };

  const handleLogout = () => {
    clearSession();
    setRole(null);
    setRoute('landing');
    window.history.pushState({}, '', '/');
  };

  /* Listen to browser back/forward */
  useEffect(() => {
    const handlePopState = () => {
      const path = window.location.pathname;
      const map: Record<string, Route> = {
        '/': 'landing',
        '/login': 'login',
        '/brand': 'brand',
        '/creator': 'creator',
      };
      const r = map[path];
      if (r) setRoute(r);
    };
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  /* Role-aware navbar content */
  const isAuthenticated = !!role;

  return (
    <div className="min-h-screen bg-[hsl(var(--background))] text-[hsl(var(--foreground))]">
      {/* Public routes — show marketing navbar */}
      {!isAuthenticated && route === 'landing' ? (
        <>
          <Navbar role={null} onRoleChange={handleLogin} />
          <main>
            <Landing />
          </main>
          <Footer />
        </>
      ) : (
        <>
          {/* Authenticated — show app navbar */}
          <Navbar role={role} onRoleChange={handleLogin} />

          {route === 'login' && (
            <main className="min-h-[calc(100vh-4rem)]">
              <Login />
            </main>
          )}

          {route === 'brand' && (
            <main className="min-h-[calc(100vh-4rem)]">
              <BrandDashboard />
            </main>
          )}

          {route === 'creator' && (
            <main className="min-h-[calc(100vh-4rem)]">
              <CreatorDashboard />
            </main>
          )}

          {/* Redirect unauthenticated users to landing if they try to access dashboards */}
          {!isAuthenticated && (route === 'brand' || route === 'creator') && (
            <main className="min-h-[calc(100vh-4rem)] flex items-center justify-center">
              <div className="text-center">
                <h2 className="text-2xl font-bold mb-2">Please log in</h2>
                <p className="text-[hsl(var(--muted-foreground))] mb-6">
                  You need to select a role to access the dashboard.
                </p>
                <button
                  onClick={() => {
                    setRoute('landing');
                    window.history.pushState({}, '', '/');
                  }}
                  className="text-[hsl(var(--primary))] hover:underline font-medium"
                >
                  Back to home
                </button>
              </div>
            </main>
          )}
        </>
      )}
    </div>
  );
}

export default App;

