/* ============================================================================
   DHAMINI — WebSocket Client
   Real-time stream verification updates (Agent 3 Proof-of-Play)

   Backend contract needed (to be implemented on FastAPI side):

   Endpoint:   WSS://barbah-sponsorplay.onrender.com/api/v1/ws/verify/{creator_id}
   Protocol:   JSON messages, text frames

   Client → Server (subscribe):
   {
     type: "subscribe",
     stream_url: "https://twitch.tv/creator_channel",
     proposal_id: "PROP-xxx",
     milestone_id: "MLS-xxx"
   }

   Server → Client (verification updates):
   {
     type: "verification_update",
     milestone_id: "MLS-xxx",
     status: "IN_PROGRESS" | "VERIFIED" | "REQUIRES_REVISION" | "FAILED",
     logo_screen_ratio_percent: 4.12,
     verbal_slogans_detected: ["Powered by Safaricom 5G"],
     audio_confidence: 0.95,
     brand_safety_status: "SAFE",
     overall_confidence_percent: 96.5,
     verification_decision: "PASSED",
     cryptographic_hash: "...",
     timestamp: "2026-11-21T..."
   }

   Server → Client (heartbeat):
   { type: "ping", timestamp: "..." }

   Client → Client (respond to heartbeat):
   { type: "pong", timestamp: "..." }
   ============================================================================ */

export type VerifyStatus =
  | "IN_PROGRESS"
  | "VERIFIED"
  | "REQUIRES_REVISION"
  | "FAILED";

export interface VerificationUpdate {
  type: "verification_update";
  milestone_id: string;
  status: VerifyStatus;
  logo_screen_ratio_percent?: number;
  verbal_slogans_detected?: string[];
  audio_confidence?: number;
  brand_safety_status?: string;
  overall_confidence_percent?: number;
  verification_decision?: string;
  cryptographic_hash?: string;
  timestamp: string;
}

export interface WSSubscribePayload {
  type: "subscribe";
  stream_url: string;
  proposal_id: string;
  milestone_id: string;
}

export interface WSMessage {
  type: string;
  [key: string]: any;
}

type UpdateHandler = (update: VerificationUpdate) => void;
type ErrorHandler = (error: Event) => void;
type ConnectHandler = () => void;
type DisconnectHandler = () => void;

class VerificationWebSocket {
  private ws: WebSocket | null = null;
  private url: string = "";
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectDelay = 2000;
  private heartbeatInterval: NodeJS.Timeout | null = null;
  private handlers = {
    onUpdate: new Set<UpdateHandler>(),
    onError: new Set<ErrorHandler>(),
    onConnect: new Set<ConnectHandler>(),
    onDisconnect: new Set<DisconnectHandler>(),
  };

  connect(creatorId: string, token?: string) {
    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    const host = "barbah-sponsorplay.onrender.com";
    this.url = `${protocol}//${host}/api/v1/ws/verify/${creatorId}`;

    this.ws = new WebSocket(this.url);

    this.ws.onopen = () => {
      this.reconnectAttempts = 0;
      this.startHeartbeat();
      this.handlers.onConnect.forEach((h) => h());
    };

    this.ws.onmessage = (event: MessageEvent) => {
      try {
        const message: WSMessage = JSON.parse(event.data);

        if (message.type === "verification_update") {
          this.handlers.onUpdate.forEach((h) => h(message as VerificationUpdate));
        } else if (message.type === "ping") {
          // Respond to heartbeat
          if (this.ws?.readyState === WebSocket.OPEN) {
            this.ws.send(JSON.stringify({ type: "pong", timestamp: Date.now() }));
          }
        }
      } catch (err) {
        console.error("Failed to parse WebSocket message", err);
      }
    };

    this.ws.onerror = (event: Event) => {
      this.handlers.onError.forEach((h) => h(event));
    };

    this.ws.onclose = () => {
      this.stopHeartbeat();
      this.handlers.onDisconnect.forEach((h) => h());
      this.attemptReconnect(creatorId, token);
    };
  }

  private attemptReconnect(creatorId: string, token?: string) {
    if (this.reconnectAttempts < this.maxReconnectAttempts) {
      this.reconnectAttempts++;
      setTimeout(() => {
        console.log(`WebSocket reconnect attempt ${this.reconnectAttempts}`);
        this.connect(creatorId, token);
      }, this.reconnectDelay * this.reconnectAttempts);
    }
  }

  private startHeartbeat() {
    this.heartbeatInterval = setInterval(() => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        this.ws.send(JSON.stringify({ type: "ping", timestamp: Date.now() }));
      }
    }, 30000);
  }

  private stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  subscribe(payload: WSSubscribePayload) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(payload));
    } else {
      console.warn("WebSocket not open, cannot subscribe");
    }
  }

  unsubscribe() {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: "unsubscribe" }));
    }
  }

  disconnect() {
    this.stopHeartbeat();
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }

  onUpdate(handler: UpdateHandler) {
    this.handlers.onUpdate.add(handler);
    return () => this.handlers.onUpdate.delete(handler);
  }

  onError(handler: ErrorHandler) {
    this.handlers.onError.add(handler);
    return () => this.handlers.onError.delete(handler);
  }

  onConnect(handler: ConnectHandler) {
    this.handlers.onConnect.add(handler);
    return () => this.handlers.onConnect.delete(handler);
  }

  onDisconnect(handler: DisconnectHandler) {
    this.handlers.onDisconnect.add(handler);
    return () => this.handlers.onDisconnect.delete(handler);
  }

  get isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN;
  }
}

export const verificationWS = new VerificationWebSocket();
export default verificationWS;

import React, { useState, useEffect, useRef } from 'react';
import { verificationWS, VerificationUpdate, VerifyStatus } from '@/lib/websocket';
import { Badge } from '@/components/ui/Badge';
import {
  ShieldCheck,
  AlertCircle,
  Loader2,
  CheckCircle2,
  Play,
  Smartphone,
} from 'lucide-react';

interface VerificationStatusProps {
  creatorId: string;
  streamUrl?: string;
  proposalId?: string;
  milestoneId?: string;
  onVerificationComplete?: (decision: string) => void;
}

const statusColors: Record<VerifyStatus, string> = {
  IN_PROGRESS: 'bg-amber-900/20 text-amber-300 border-amber-500/30 animate-pulse',
  VERIFIED: 'bg-emerald-900/20 text-emerald-300 border-emerald-500/30',
  REQUIRES_REVISION: 'bg-amber-900/20 text-amber-300 border-amber-500/30',
  FAILED: 'bg-red-900/20 text-red-300 border-red-500/30',
};

const statusLabels: Record<VerifyStatus, string> = {
  IN_PROGRESS: 'Verifying...',
  VERIFIED: 'Proof-of-Play Verified',
  REQUIRES_REVISION: 'Requires Revision',
  FAILED: 'Verification Failed',
};

export function VerificationStatus({
  creatorId,
  streamUrl,
  proposalId,
  milestoneId,
  onVerificationComplete,
}: VerificationStatusProps) {
  const [status, setStatus] = useState<VerifyStatus | null>(null);
  const [update, setUpdate] = useState<VerificationUpdate | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Connect WebSocket
    verificationWS.connect(creatorId);

    const unsubConnect = verificationWS.onConnect(() => setIsConnected(true));
    const unsubDisconnect = verificationWS.onDisconnect(() => setIsConnected(false));
    const unsubError = verificationWS.onError(() => setError('Connection error'));

    const unsubUpdate = verificationWS.onUpdate((verificationUpdate) => {
      setUpdate(verificationUpdate);
      setStatus(verificationUpdate.status);

      if (
        verificationUpdate.status === 'VERIFIED' ||
        verificationUpdate.status === 'FAILED'
      ) {
        onVerificationComplete?.(verificationUpdate.status);
      }
    });

    // Subscribe to verification stream if we have the needed info
    if (streamUrl && proposalId && milestoneId && !isSubscribed) {
      setIsSubscribed(true);
      verificationWS.subscribe({
        type: 'subscribe',
        stream_url: streamUrl,
        proposal_id: proposalId,
        milestone_id: milestoneId,
      });
    }

    return () => {
      unsubConnect();
      unsubDisconnect();
      unsubError();
      unsubUpdate();
      verificationWS.unsubscribe();
    };
  }, [creatorId, streamUrl, proposalId, milestoneId, isSubscribed, onVerificationComplete]);

  const getStatusIcon = () => {
    switch (status) {
      case 'IN_PROGRESS':
        return <Loader2 className="h-5 w-5 animate-spin text-amber-400" />;
      case 'VERIFIED':
        return <CheckCircle2 className="h-5 w-5 text-emerald-400" />;
      case 'REQUIRES_REVISION':
        return <AlertCircle className="h-5 w-5 text-amber-400" />;
      case 'FAILED':
        return <AlertCircle className="h-5 w-5 text-red-400" />;
      default:
        return <Play className="h-5 w-5 text-[hsl(var(--muted-foreground))]" />;
    }
  };

  if (!streamUrl || !proposalId || !milestoneId) {
    return (
      <div className="d-card p-6 text-center">
        <div className="flex items-center justify-center gap-3 mb-4">
          <Smartphone className="h-6 w-6 text-[hsl(var(--muted-foreground))]" />
          <span className="text-sm text-[hsl(var(--muted-foreground))]">
            Ready to verify stream
          </span>
        </div>
        <p className="text-xs text-[hsl(var(--muted-foreground))] mb-6">
          Submit a stream link to begin real-time AI verification.
        </p>
      </div>
    );
  }

  return (
    <div className="d-card p-6">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3 className="font-bold text-[hsl(var(--foreground))] mb-1">
            Real-Time Verification
          </h3>
          <p className="text-xs text-[hsl(var(--muted-foreground))]">
            Agent 3: Multimodal Verifier
          </p>
        </div>
        <Badge variant={isConnected ? 'green' : 'slate'}>
          {isConnected ? 'Live' : 'Connecting...'}
        </Badge>
      </div>

      <div className="space-y-4">
        {/* Status */}
        <div
          className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${
            statusColors[status || 'IN_PROGRESS']
          }`}
        >
          {getStatusIcon()}
          <div>
            <p className="font-medium text-[hsl(var(--foreground))]">
              {statusLabels[status || 'IN_PROGRESS']}
            </p>
            {update && (
              <p className="text-xs text-[hsl(var(--muted-foreground))]">
                {update.verification_decision
                  ? `Decision: {update.verification_decision}`
                  : ''}
                {update.overall_confidence_percent !== undefined
                  ? ` • Confidence: {update.overall_confidence_percent}%`
                  : ''}
              </p>
            )}
          </div>
        </div>

        {/* Metrics */}
        {update && (
          <div className="grid grid-cols-2 gap-4">
            <div className="p-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">
              <p className="text-xs text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                Logo Screen Time
              </p>
              <p className="font-bold text-[hsl(var(--foreground))]">
                {update.logo_screen_ratio_percent?.toFixed(2) ?? 0}%
              </p>
            </div>
            <div className="p-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">
              <p className="text-xs text-[hsl(var(--muted-foreground))] uppercase tracking-wider">
                Audio Confidence
              </p>
              <p className="font-bold text-[hsl(var(--foreground))]">
                {Math.round((update.audio_confidence ?? 0) * 100)}%
              </p>
            </div>
          </div>
        )}

        {/* Brand safety */}
        {update && update.brand_safety_status && (
          <div className="flex items-center justify-between p-3 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">
            <span className="text-xs text-[hsl(var(--muted-foreground))]">
              Brand Safety
            </span>
            <Badge
              variant={
                update.brand_safety_status === 'SAFE' ? 'green' : 'terracotta'
              }
            >
              {update.brand_safety_status}
            </Badge>
          </div>
        )}

        {/* Error */}
        {error && (
          <div className="p-3 rounded-xl border border-red-500/30 bg-red-900/20 text-red-300 text-sm">
            {error}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  ArrowRight,
  Link,
  Play,
  Smartphone,
  ShieldCheck,
  Clock,
  Download,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Input } from '@/components/ui/Input';
import { api } from '@/lib/api';
import { VerificationStatus } from '@/components/VerificationStatus';

interface CreatorDeliverablesProps {
  onNavigate: (path: string) => void;
}

export const CreatorDeliverables = ({ onNavigate }: CreatorDeliverablesProps) => {
  /* Read creator_id from URL query params */
  const [searchParams] = useState(() => new URLSearchParams(window.location.search));
  const creatorId = searchParams.get('creator_id') || 'creator-001';

  const navigate = useNavigate();
  const [streamUrl, setStreamUrl] = useState('');
  const [proposalId, setProposalId] = useState('');
  const [milestoneId, setMilestoneId] = useState('');
  const [notes, setNotes] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submissionResult, setSubmissionResult] = useState<any>(null);
  const [verificationDecision, setVerificationDecision] = useState<string | null>(null);

  const handleSubmitDeliverable = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmissionResult(null);

    try {
      const result = await api.submitDeliverable({
        proposal_id: proposalId,
        creator_id: creatorId,
        milestone_id: milestoneId,
        deliverable_type: 'STREAM_LINK',
        media_url: streamUrl,
        notes,
      });
      setSubmissionResult(result);
      setVerificationDecision(result.decision);
    } catch (err: any) {
      setSubmissionResult({ error: err.message || 'Submission failed' });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleBack = () => {
    onNavigate(`/creator?creator_id=${creatorId}`);
  };

  return (
    <div className="min-h-screen bg-[hsl(var(--background))]">
      {/* Top App Bar */}
      <div className="border-b border-[hsl(var(--border))] bg-[hsl(var(--card))]/50 backdrop-blur sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 py-6">
            <div className="flex items-center gap-3 cursor-pointer" onClick={handleBack}>
              <ArrowRight className="h-5 w-5 text-[hsl(var(--muted-foreground))]" />
              <span className="font-medium text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))] transition-colors">
                Back to Dashboard
              </span>
            </div>

            <div className="flex items-center gap-4 w-full lg:w-auto">
              <h1 className="text-xl font-bold text-[hsl(var(--foreground))]">
                Upload Deliverable
              </h1>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid lg:grid-cols-2 gap-8">
          {/* Submission Form */}
          <Card padding="md">
            <CardHeader>
              <CardTitle className="text-lg">Submit Stream for Verification</CardTitle>
              <CardDescription>
                Paste your stream link. Agent 3 will verify logo visibility,
                verbal brand mentions, and brand safety in real time.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-5">
              <form onSubmit={handleSubmitDeliverable} className="space-y-4">
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-[hsl(var(--foreground))]">
                    Proposal ID
                  </label>
                  <Input
                    value={proposalId}
                    onChange={(e) => setProposalId(e.target.value)}
                    placeholder="e.g. PROP-abc123"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-[hsl(var(--foreground))]">
                    Milestone ID
                  </label>
                  <Input
                    value={milestoneId}
                    onChange={(e) => setMilestoneId(e.target.value)}
                    placeholder="e.g. MLS-01"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-[hsl(var(--foreground))]">
                    Stream Link (Twitch / YouTube / TikTok)
                  </label>
                  <Input
                    value={streamUrl}
                    onChange={(e) => setStreamUrl(e.target.value)}
                    placeholder="https://twitch.tv/thebeast_ke"
                    required
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-sm font-semibold text-[hsl(var(--foreground))]">
                    Notes (optional)
                  </label>
                  <Input
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="Any context for the verifier..."
                  />
                </div>

                <Button
                  variant="gold"
                  className="w-full"
                  isLoading={isSubmitting}
                  disabled={isSubmitting || !streamUrl || !proposalId || !milestoneId}
                  leftIcon={<Play className="h-4 w-4" />}
                >
                  Submit for AI Verification
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Submission Result */}
          {submissionResult && (
            <Card padding="md" className="border-[hsl(var(--secondary))]/30 shadow-[var(--shadow-green)]">
              <CardHeader>
                <CardTitle className="text-lg">Verification Result</CardTitle>
                <CardDescription>
                  Agent 3 has reviewed your deliverable.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center gap-3">
                  <ShieldCheck className="h-6 w-6 text-emerald-400" />
                  <span className="font-bold text-[hsl(var(--foreground))]">
                    Status: {submissionResult.decision}
                  </span>
                </div>

                <div className="space-y-3 text-sm">
                  <div className="flex justify-between">
                    <span className="text-[hsl(var(--muted-foreground))]">Decision</span>
                    <span className="font-medium text-[hsl(var(--foreground))]">
                      {submissionResult.decision}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-[hsl(var(--muted-foreground))]">Next Step</span>
                    <span className="font-medium text-[hsl(var(--foreground))]">
                      {submissionResult.next_step}
                    </span>
                  </div>
                </div>

                {submissionResult.certificate && (
                  <div className="p-4 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">
                    <h4 className="text-sm font-bold text-[hsl(var(--foreground))] mb-2">
                      Proof-of-Play Certificate
                    </h4>
                    <div className="space-y-1 text-xs text-[hsl(var(--muted-foreground))]">
                      <div>ID: {submissionResult.certificate.certificate_id}</div>
                      <div>Confidence: {submissionResult.certificate.overall_confidence_percent}%</div>
                      <div>Logo Occupancy: {submissionResult.certificate.logo_screen_ratio_percent}%</div>
                    </div>
                  </div>
                )}

                <div className="flex gap-3">
                  <Button
                    variant="outline"
                    onClick={() => setSubmissionResult(null)}
                    className="flex-1"
                  >
                    <Clock className="h-4 w-4 mr-2" />
                    New Submission
                  </Button>
                  <Button
                    variant="secondary"
                    onClick={() => {
                      onNavigate(`/creator?creator_id=${creatorId}`);
                    }}
                    className="flex-1"
                  >
                    <ArrowRight className="h-4 w-4 mr-2" />
                    Back to Dashboard
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          {/* Real-time Verification Status (WebSocket) */}
          {proposalId && milestoneId && streamUrl && (
            <Card padding="md">
              <CardHeader>
                <CardTitle className="text-lg">Live Verification</CardTitle>
                <CardDescription>
                  Watch Agent 3 verify your stream in real time.
                </CardDescription>
              </CardHeader>
              <CardContent>
                <VerificationStatus
                  creatorId={creatorId}
                  streamUrl={streamUrl}
                  proposalId={proposalId}
                  milestoneId={milestoneId}
                  onVerificationComplete={(decision) => {
                    setVerificationDecision(decision);
                  }}
                />
              </CardContent>
            </Card>
          )}
        </div>

        {/* Info Section */}
        <div className="mt-8 grid md:grid-cols-3 gap-6">
          <Card padding="md" className="text-center">
            <div className="h-10 w-10 rounded-lg bg-blue-900/20 text-blue-400 flex items-center justify-center mx-auto mb-3">
              <Smartphone className="h-5 w-5" />
            </div>
            <h4 className="font-bold text-[hsl(var(--foreground))] mb-2">
              Paste Stream Link
            </h4>
            <p className="text-sm text-[hsl(var(--muted-foreground))]">
              Twitch, YouTube, TikTok, or any public stream URL.
            </p>
          </Card>

          <Card padding="md" className="text-center">
            <div className="h-10 w-10 rounded-lg bg-purple-900/20 text-purple-400 flex items-center justify-center mx-auto mb-3">
              <ShieldCheck className="h-5 w-5" />
            </div>
            <h4 className="font-bold text-[hsl(var(--foreground))] mb-2">
              AI Verification
            </h4>
            <p className="text-sm text-[hsl(var(--muted-foreground))]">
              Logo detection, verbal mentions, brand safety — all automated.
            </p>
          </Card>

          <Card padding="md" className="text-center">
            <div className="h-10 w-10 rounded-lg bg-emerald-900/20 text-emerald-400 flex items-center justify-center mx-auto mb-3">
              <Download className="h-5 w-5" />
            </div>
            <h4 className="font-bold text-[hsl(var(--foreground))] mb-2">
              Get Paid
            </h4>
            <p className="text-sm text-[hsl(var(--muted-foreground))]">
              Verified milestones trigger instant PayPal payout + M-Pesa.
            </p>
          </Card>
        </div>
      </div>
    </div>
  );
};

