                  <div className="border-2 border-dashed rounded-xl border-[hsl(var(--border))] bg-[hsl(var(--background))]/30 p-4 text-center hover:border-[hsl(var(--primary))]/50 transition-colors cursor-pointer relative">
                    <input
                      type="file"
                      accept="image/*"
